function ib.weatherStrength(Qo)
local Ro=ib.fx(Qo)
local So=Ro.dmg/Ro.cd/Ro.hp/Ro.speed*(1+(Ro.range-1)/2)
for To,Uo in pairs(Ro.kinds)do
So=So*(1+W.rogueShare(To)*Uo)
end
if Ro.ice>0 then
local Vo=W.rogueShare(ydd[1724])
So=So*(Vo+(1-Vo)/(1-Ro.ice+Ro.ice/db.modFactor(ydd[1843])))
end
if Ro.fly>0 then
So=So*(1-Ro.fly*0.5)
end
if Ro.noCC then
So=So*0.95
end
if Ro.shroud then
So=So*0.9
end
if Ro.zap then
So=So*0.85
end
return So/ib.weatherK(Qo)
end
ib.WEATHER_K_MIN,ib.WEATHER_K_MAX,ib.WEATHER_K_RUNS=0.5,4,10
function ib.weatherK(Wo)
local Xo=Wo and type(N.hunt)==ydd[1593]and type(N.hunt.wk)==ydd[1593]and N.hunt.wk[tostring(Wo)]or nil
return type(Xo)==ydd[1593]and tonumber(Xo.k)or 1
end
function ib.weatherLearn()
if W.withOthers or#game:GetService(ydd[506]):GetPlayers()>1 then
return
end
local Yo=W.huntWeather or ib.weatherNow()
local Zo,_o=W.pred,W.calRun
if not Yo or type(Zo)~=ydd[1593]or type(_o)~=ydd[1593]then
return
end
local function ap(bp,cp)
return type(bp)==ydd[1593]and tonumber(bp[cp]or bp[tostring(cp)])or nil
end
local dp={}
for ep=2,W.wave()do
local fp,gp=ap(_o.alive,ep),ap(Zo.aliveAt,ep)
if fp and gp and fp>0 and gp>0 then
table.insert(dp,fp/gp)
end
end
if#dp<3 then
return
end
table.sort(dp)
local ip=dp[math.ceil(#dp/2)]
N.hunt.wk=type(N.hunt.wk)==ydd[1593]and N.hunt.wk or{}
local jp=N.hunt.wk[tostring(Yo)]
local kp=math.min(ib.WEATHER_K_RUNS-1,type(jp)==ydd[1593]and tonumber(jp.n)or 0)
local lp=ib.weatherK(Yo)
local mp=math.exp((kp*math.log(lp)+math.log(lp*ip))/(kp+1))
mp=Q.clamp(mp,ib.WEATHER_K_MIN,ib.WEATHER_K_MAX)
N.hunt.wk[tostring(Yo)]={k=mp,n=(type(jp)==ydd[1593]and tonumber(jp.n)or 0)+1,at=os.time()}
E.log(1,ydd[1844],string.format(ydd[1845],tostring(Yo),ip,tostring(Yo),mp,lp,N.hunt.wk[tostring(Yo)].n))
end
function ib.cardGems(np,op)
local pp=0
local qp=ib.pearlsFrom(op+1,50)
for rp,tp in pairs(type(np.effects)==ydd[1593]and np.effects or{})do
if type(tp)==ydd[1593]then
local up=tonumber(tp.amount)or 0
if tp.type==ydd[1846]then
pp=pp+math.abs(up)*qp*M.pearlValue
elseif tp.type==ydd[1847]then
local vp,wp=pcall(U.rewardValue,tp.reward)
if vp then
pp=pp+(tonumber(wp)or 0)
end
elseif tp.type==ydd[1848]then
pp=pp+up*ib.STARFALL_GEMS
elseif tp.type==ydd[1849]then
pp=pp+up*100
end
end
end
if np.option_type==ydd[1850]then
pp=pp+ib.HARD_GEMS
end
if np.weather then
local yp=np.weather~=ib.weatherNow()
if yp and np.weather==ydd[1795]then
pp=pp+ib.starfallRemnants(50-(tonumber(op)or 0))*(L.ITEM_VALUE.star_remnant_limited or 25)
end
local zp=ib.board()
if yp and zp and np.weather~=ydd[1801]and not zp.weathers[np.weather]then
pp=pp+(1000+5000*M.pearlValue+50*(L.ITEM_VALUE.star_remnant_limited or 25))/ib.WEATHERS
end
end
return pp
end
