aq.pearls=aq.pearls+(ib.SKIN_PRICE[kq.rarity]or 0)
end
end
for pq,qq in ipairs(hq)do
local rq=qq.skin and qq.skin._skin_id and Yp[qq.skin._skin_id]
if not(rq and rq._skin_set==ib.SKIN_SET)then
for sq,tq in pairs(Yp)do
if type(tq)==ydd[1593]and tq._skin_set==ib.SKIN_SET and ib.skinFits(qq.unit_id,tq)then
local uq=sq..ydd[1876]
if _p[uq]then
