else
table.insert(aq.missing,{item=uq,unitName=R.name(qq.unit_id),name=tq.name,boost=tonumber(tq._damage_boost)or 0,drop=ib.SKIN_DROP[tq._skin_rarity]or 0})
end
end
end
end
end
return aq
end
