xr=xr+kr.sell[yr].pearls
end
local zr=tonumber(L.cur(ydd[1871]))or 0
local Ar=Q.now()
local Br,Cr=E.request(ydd[1905],ydd[1906],wr)
while Q.now()-Ar<5 and(tonumber(L.cur(ydd[1871]))or 0)<=zr do
