function hb.gainXp(vM,wM)
local xM,yM=tonumber(vM.xp)or 0,hb.xpFor(vM.unit_id,hb.cap(vM))
local zM=math.max(0,yM-xM)
if zM<=0 or(wM or 0)<=0 then
return 0,0
end
local AM=math.min(wM,zM)
local BM=hb.base(vM)
if BM<=0 then
return 0,AM
end
return hb.share(vM.unit_id)*(hb.score(hb.whatIf(vM,{xp=xM+AM}))/BM-1)*100,AM
end
function hb.gainFuse(CM)
