local EM=hb.whatIf(CM,{xp=math.max(tonumber(CM.xp)or 0,hb.xpFor(CM.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return hb.share(CM.unit_id)*(hb.score(EM)/DM-1)*100+5
end
