function hb.relicWorth(FM,GM)
local HM=GM._unique_item_data and GM._unique_item_data._unique_relic_data
if not HM then
return 0
end
local IM=L.Items[GM.item_id]or{}
local JM,KM=R.types(FM.unit_id)
if IM.main_damage_type and IM.main_damage_type~=ydd[2241]and IM.main_damage_type~=KM then
return 0
end
local LM,MM=0,0
for NM,OM in pairs(HM._core_damage_type_buffs or{})do
if JM[OM.damage_type]then
LM=LM+(tonumber(OM.mul)or 0)+(tonumber(OM.add_upg)or 0)*0.01+(tonumber(OM.pen)or 0)*0.001
MM=MM+(tonumber(OM.crit)or 0)
end
end
LM=LM+MM*0.5
local PM=R.rows(FM.unit_id)
local QM=PM and PM[PM.max]
local RM=(QM and tonumber(QM.cd)or 0)*R.mult(FM,ydd[1749])
for SM,TM in pairs(HM._unique_relic_effects or{})do
local UM=type(TM.params)==ydd[1593]and TM.params or{}
if TM.id==ydd[2242]then
local VM=math.min(1,(tonumber(UM.extra_damage)or 0)*RM/math.max(1,tonumber(UM.time_interval)or 40))
local WM=R.DRONES and R.DRONES[FM.unit_id]
if WM and WM.late and RM>0 then
local XM=1/RM
VM=VM*XM/(XM+(tonumber(WM.max)or 0)*(tonumber(WM.late.dmg)or 0)*(tonumber(WM.hits)or 1)/math.max(0.1,tonumber(WM.late.cd)or 4))
end
LM=LM+VM
elseif TM.id==ydd[2243]then
LM=LM+(tonumber(UM.dmg_buff)or 0)*0.25
elseif TM.id==ydd[2244]then
LM=LM+(tonumber(UM.dmg_buff)or 0)*MM
elseif TM.id==ydd[2245]then
if JM.magic then
LM=0
else
LM=LM+(tonumber(UM.dmg_buff)or 0)*0.3
end
elseif TM.id==ydd[2246]then
if JM.water_damage then
LM=LM+0.05
end
end
end
return LM
end
