function V.evolve(PR,QR)
local RR=L.session()
local SR=RR.collection:get_unit_by_uuid(PR.uuid)
if not SR then
return false,ydd[2327]
end
local TR,UR=0,{}
for VR,WR in pairs(RR.profile_data.collection.owned_units)do
if WR.unit_id==PR.to then
TR=TR+1
UR[VR]=true
end
end
local XR,YR=E.request(ydd[1685],ydd[2328],PR.uuid)
task.wait(2)
local ZR=RR.collection:get_unit_by_uuid(PR.uuid)
local _R=0
for aS,bS in pairs(RR.profile_data.collection.owned_units)do
if bS.unit_id==PR.to then
_R=_R+1
if not UR[aS]then
if M.fuseXpUnit==PR.uuid then
M.fuseXpUnit,M.fuseXpId=aS,PR.to
E.saveSoon()
end
if M.fuseUnit==PR.uuid then
M.fuseUnit=aS
E.saveSoon()
end
end
end
end
if _R>TR then
local cS={}
for dS,eS in ipairs(PR.items or{})do
table.insert(cS,string.format(ydd[2329],(L.Items[eS.id]or{}).name or eS.id,eS.amount))
end
for fS,gS in ipairs(PR.eats or{})do
table.insert(cS,string.format(ydd[2330],gS.amount,R.name(gS.id)))
end
local hS=string.format(ydd[2331],R.name(PR.from),R.name(PR.to),Q.fmt(PR.scoreFrom or 0),Q.fmt(PR.scoreTo or 0))
ab.add(ydd[2332]..hS,1,ydd[2333],(QR or ydd[2334])..(#cS>0 and(ydd[2335]..table.concat(cS,ydd[1701]))or ydd[520]))
E.log(1,ydd[2336],hS..ydd[2337]..(QR or ydd[2334])..(#cS>0 and(ydd[2335]..table.concat(cS,ydd[1701]))or ydd[520]))
U._sigAt=nil
pcall(eb.refresh)
return true,R.name(PR.to)..ydd[2338]
end
E.log(1,ydd[2336],ydd[2339]..R.name(PR.from)..ydd[1933]..tostring(YR)..ydd[2340]..tostring(ZR and ZR.unit_id))
return false,ydd[2341]..tostring(YR)..ydd[1934]
end
