function V.evolveBuy(IS)
local JS=V.evolveBuyPlan(IS)
if not JS or E.where~=ydd[1660]then
return false
end
if E.req.back.evobuy and Q.now()<E.req.back.evobuy then
return false
end
local KS=(L.Items[JS.item]or{}).name or JS.item
local LS=eb.have(JS.item)
local MS,NS=E.request(ydd[2348],ydd[1915],JS.item,ydd[1610],ydd[1916],ydd[1752])
local OS=Q.now()
while Q.now()-OS<4 and eb.have(JS.item)<=LS do
task.wait(0.25)
end
if eb.have(JS.item)>LS then
ab.add(KS,JS.cost,tostring(JS.currency),ydd[2349]..R.name(IS.from)..ydd[2350])
if E.notify then
E.notify(ydd[2346],ydd[2164]..KS..ydd[2290]..R.name(IS.from),ydd[2166])
end
pcall(eb.refresh)
return true
end
E.log(1,ydd[2167],string.format(ydd[2351],KS,tostring(MS and NS or ydd[1898])))
E.backoff(ydd[2348],900)
return false
