function V.autoEvolve()
if not M.autoEvolve or M.evolveUnit==ydd[520]then
return
end
local PS=L.session()
if not(PS and PS.collection:get_unit_by_uuid(M.evolveUnit))then
return V.pickDone(ydd[2352],ydd[2346],ydd[2353],ydd[2354])
end
local QS
for RS,TS in ipairs(N.goals or{})do
if TS.pinned and TS.uuid==M.evolveUnit then
QS=TS
break
end
end
if not QS then
local US=PS.collection:get_unit_by_uuid(M.evolveUnit)
local VS=L.Units[US.unit_id]
if not(VS and VS.evolve and VS.evolve.evolve_unit)then
V.pickDone(ydd[2352],ydd[2346],R.name(US.unit_id)..ydd[2355],ydd[2354])
end
return
end
V.pickNote.autoEvolve=nil
if not QS.ready and V.evolveBuy(QS)then
for WS,XS in ipairs(N.goals or{})do
if XS.pinned and XS.uuid==M.evolveUnit then
QS=XS
break
end
end
end
if not QS.ready then
return
end
local YS={}
for ZS,_S in ipairs(R.equipped())do
YS[_S.uuid]=true
end
local aT=V.evoEats(QS,YS)
if aT then
V.pickNote.autoEvolve=aT
return
end
if(V.evoBlocked[QS.uuid]or 0)>=os.time()then
return
end
local bT,cT=V.evolve(QS,ydd[2356])
if bT then
V.pickDone(ydd[2352],ydd[2346],cT)
else
V.evoBlocked[QS.uuid]=os.time()+3600
V.pickNote.autoEvolve=cT
end
