function V.fuseFuel(gT,hT)
local iT=L.session()
local jT={[gT.uuid]=true,[M.evolveUnit]=true,[M.fuseXpUnit]=true}
local kT={}
for lT,mT in ipairs(R.equipped())do
jT[mT.uuid]=true
end
for nT,oT in ipairs(N.savedTeam or{})do
jT[oT]=true
end
for pT,qT in ipairs(N.train and N.train.on and N.train.on.base or{})do
jT[qT]=true
end
for rT,sT in ipairs(N.goals or{})do
jT[sT.uuid]=true
for tT,uT in ipairs(sT.eats or{})do
kT[uT.id]=true
end
end
for vT,wT in ipairs(N.str and N.str.core or{})do
jT[wT]=true
end
local xT=eb.strongest(10)
local yT,zT={},0
for AT,BT in pairs(iT.profile_data.collection.owned_units)do
local CT=iT.collection:get_unit_by_uuid(AT)or BT
local ET,FT,GT=pcall(L.USC.is_unit_good_for_fusion,gT,CT)
if ET and FT and not(BT._locked or CT._locked)and not jT[AT]and not kT[CT.unit_id]and not(BT._equipped_relic or CT._equipped_relic)and not(BT.shiny or CT.shiny)and not R.trait(CT)and not(BT.further_modifiers and BT.further_modifiers.limit_break)then
local HT=eb.fodderOrder(CT.unit_id)
if HT and not xT[AT]then
local IT,JT=pcall(R.score,CT)
table.insert(yT,{uuid=AT,id=CT.unit_id,pts=tonumber(GT)or 1,sc=IT and JT or 0,order=HT})
zT=zT+(tonumber(GT)or 1)
end
end
end
table.sort(yT,function(KT,LT)
if KT.order~=LT.order then
return KT.order<LT.order
end
if KT.sc~=LT.sc then
return KT.sc<LT.sc
end
return KT.uuid<LT.uuid
end)
local NT,OT={},0
for PT,QT in ipairs(yT)do
if OT>=hT then
break
end
table.insert(NT,QT)
OT=OT+QT.pts
end
return NT,OT,zT
end
