V.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function V.xpFodder(dV)
local eV=L.session()
local fV=V.FUSE_RANK[M.fuseXpRarity]or 2
local gV={[dV.uuid]=true,[M.evolveUnit]=true,[M.fuseUnit]=true}
for hV,iV in ipairs(R.equipped())do
gV[iV.uuid]=true
end
for jV,kV in ipairs(N.savedTeam or{})do
gV[kV]=true
end
for lV,mV in ipairs(N.train and N.train.on and N.train.on.base or{})do
gV[mV]=true
end
local nV,oV={},0
for pV,qV in pairs(eV.profile_data.collection.owned_units)do
local rV=L.Units[qV.unit_id]
local sV=rV and V.FUSE_RANK[rV.rarity]
if sV and sV<=fV and not gV[pV]then
local tV=eV.collection:get_unit_by_uuid(pV)or qV
if not(qV._locked or tV._locked)and not(qV._equipped_relic or tV._equipped_relic)then
local uV,vV=pcall(L.USC.calculate_xp_gain_from_fuse,dV,{tV},eV)
vV=uV and tonumber(vV)or 0
if vV>0 then
table.insert(nV,{uuid=pV,id=qV.unit_id,xp=vV,rarity=rV.rarity})
oV=oV+vV
end
end
end
end
table.sort(nV,function(wV,xV)
if wV.xp~=xV.xp then
return wV.xp<xV.xp
end
return wV.uuid<xV.uuid
end)
local yV=math.max(0,hb.xpFor(dV.unit_id,hb.cap(dV))-(tonumber(dV.xp)or 0))
local zV,AV={},0
for BV,CV in ipairs(nV)do
if AV>=yV then
break
end
table.insert(zV,CV)
AV=AV+CV.xp
end
return zV,AV,yV,oV
end
function V.fuseXpTarget(DV)
