return ydd[2377]
end
local NV,OV,PV=V.xpFodder(MV)
local QV={}
for RV,SV in ipairs(NV)do
QV[SV.rarity]=(QV[SV.rarity]or 0)+1
end
local TV={}
for UV,VV in ipairs({ydd[2378],ydd[523],ydd[1874]})do
if QV[VV]then
table.insert(TV,QV[VV]..ydd[1758]..VV)
end
end
local WV,XV=hb.level(MV),hb.cap(MV)
local YV
if PV<=0 then
YV=string.format(ydd[2379],R.name(MV.unit_id),WV,XV)
elseif#NV==0 then
YV=string.format(ydd[2380],R.name(MV.unit_id),WV,XV)
else
YV=string.format(ydd[2381],R.name(MV.unit_id),WV,XV,table.concat(TV,ydd[1701]),Q.fmt(OV),hb.level({unit_id=MV.unit_id,xp=(tonumber(MV.xp)or 0)+math.min(OV,PV)}))
end
YV=YV..ydd[2382]..tostring(M.fuseXpRarity)..ydd[2383]
