function V.autoFuseXp()
if not M.autoFuseXp or M.fuseXpUnit==ydd[520]then
return
end
local ZV=L.session()
local _V=V.fuseXpTarget(ZV)
if not _V then
return
end
local aW=R.name(_V.unit_id)
local bW,cW,dW=V.xpFodder(_V)
if dW<=0 then
V.pickNote.autoFuseXp=nil
return
end
if#bW==0 then
V.pickNote.autoFuseXp=ydd[2384]
return
end
if os.time()-(tonumber(M.fuseXpOnAt)or 0)<30 then
V.pickNote.autoFuseXp=ydd[2385]
return
end
V.pickNote.autoFuseXp=nil
if E.req.back.fuseXp and Q.now()<E.req.back.fuseXp then
return
end
V.fuseBatch=V.fuseBatch or 50
local eW,fW,gW=0,0,{}
while E.alive and eW<10 and not N.pauseAll do
if eW>0 then
local hW,iW,jW=V.xpFodder(ZV.collection:get_unit_by_uuid(M.fuseXpUnit)or _V)
bW,dW={},jW
for kW,lW in ipairs(hW)do
if not gW[lW.uuid]then
table.insert(bW,lW)
end
end
if dW<=0 or#bW==0 then
break
end
end
local mW={}
for nW=1,math.min(V.fuseBatch,#bW)do
table.insert(mW,bW[nW].uuid)
end
local oW=tonumber((ZV.collection:get_unit_by_uuid(M.fuseXpUnit)or _V).xp)or 0
local pW=Q.now()
local qW,rW=E.request(ydd[2386],ydd[2387],M.fuseXpUnit,mW)
if not qW and(rW==ydd[1663]or rW==ydd[1662])then
if rW==ydd[1662]or fW>=3 then
break
end
fW=fW+1
task.wait(3.5)
continue
end
while Q.now()-pW<5 and(tonumber((ZV.collection:get_unit_by_uuid(M.fuseXpUnit)or _V).xp)or 0)<=oW do
task.wait(0.1)
end
local sW=tonumber((ZV.collection:get_unit_by_uuid(M.fuseXpUnit)or _V).xp)or 0
if sW>oW then
eW=eW+1
for tW,uW in ipairs(mW)do
gW[uW]=true
