function cb.upgradeGain(Tcb,Ucb,Vcb,Wcb,Xcb,Ycb)
local Zcb,_cb=Ucb[Vcb],Ucb[Vcb+1]
local adb=(Zcb.cd>0 and Zcb.damage/Zcb.cd or 0)
local bdb=(_cb.cd>0 and _cb.damage/_cb.cd or 0)*R.aoe(_cb.atk,_cb.range)/math.max(0.3,R.aoe(Zcb.atk,Zcb.range))
local cdb=adb>0 and Tcb*(bdb/adb-1)or(Ycb or 0)
local ddb=Ucb[Vcb+2]
if ddb and Vcb+1<Ucb.max and ddb.cd>0 and _cb.cd>0 and adb>0 then
local edb=Tcb*((ddb.damage/ddb.cd)/adb-1)
local fdb=Wcb+ddb.cost*Xcb
if edb/fdb>cdb/Wcb then
cdb=cdb+(edb/fdb*Wcb-cdb)*0.5
end
end
local gdb=(_cb.range or 0)>(Zcb.range or 0)and(1+((_cb.range-Zcb.range)/math.max(1,Zcb.range)))or 1
return math.max(0,cdb)*gdb
end
function cb.dpsFor(hdb,idb)
if idb<=0 then
return 0
end
local jdb={}
for kdb,ldb in ipairs(hdb)do
if not ldb.farm and ldb.gain>0 then
table.insert(jdb,ldb)
end
end
table.sort(jdb,function(mdb,ndb)
return mdb.gain/mdb.cost>ndb.gain/ndb.cost
end)
local odb,pdb=0,0
for qdb,rdb in ipairs(jdb)do
if idb<=0 then
break
end
pdb=rdb.gain/rdb.cost
local sdb=math.min(1,idb/rdb.cost)
odb=odb+rdb.gain*sdb
idb=idb-rdb.cost*sdb
end
return odb+math.max(0,idb)*pdb*0.7
end
function cb.shieldDps(tdb,udb,vdb,wdb,xdb,ydb,zdb)
if(wdb or 0)<=0 or(tdb or 0)<=0 or(xdb or 0)<=0 then
return tdb or 0
end
udb,vdb,ydb=math.max(0.3,udb or 2),math.max(1,vdb or 1),ydb or 1
local Adb=tdb*ydb*udb/vdb
return xdb*vdb/((wdb/math.max(1,zdb or 1)+math.max(1,xdb/Adb))*udb)/ydb
end
function cb.shieldGain(Bdb,Cdb,Ddb,Edb,Fdb,Gdb,Hdb,Idb)
local Jdb,Kdb=R.attackInfo(Cdb.atk,Cdb.range),R.attackInfo(Edb.atk,Edb.range)
local Ldb=cb.shieldDps(Bdb,(tonumber(Cdb.cd)or 2)*(Hdb or 1),Jdb.n,Fdb,Gdb,Idb,Jdb.hits)
local Mdb=cb.shieldDps(Ddb,(tonumber(Edb.cd)or 2)*(Hdb or 1),Kdb.n,Fdb,Gdb,Idb,Kdb.hits)
local Ndb=math.max(0,((tonumber(Edb.range)or 0)-(tonumber(Cdb.range)or 0))/math.max(1,tonumber(Cdb.range)or 1))
return math.max(0,Mdb-Ldb)+Ldb*Ndb
end
function cb.shieldWork(Odb,Pdb,Qdb,Rdb,Sdb,Tdb,Udb,Vdb,Wdb)
if(Rdb or 0)<=0 then
return 0
end
local Xdb=3*Rdb*(Sdb or 1)/math.max(1,Tdb or 20)
if(Qdb or 0)>=Xdb then
return 0
end
return math.max(1,Odb or 1)*math.max(1,Wdb or 1)/math.max(0.3,Pdb or 2)*math.min(Udb or 0,Vdb or 0)
end
function cb.holdGain(Ydb,Zdb,_db,aeb)
if not Ydb or(Zdb or 0)<=0 then
return 0
end
local beb,ceb=tonumber(Ydb.stun)or 0,tonumber(Ydb.slowTime)or 0
if beb<=0 and ceb<=0 then
return 0
end
local deb,eeb=beb>0 and beb or ceb,beb>0 and 1 or(tonumber(Ydb.slowPct)or 0.3)
local feb=eeb*deb/(deb+(tonumber(Ydb.ccCd)or 8))
local geb=feb/math.max(0.1,1-feb)
return Zdb*geb*Q.clamp(_db or 0.5,0,1)*math.min(1,(tonumber(Ydb.n)or 1)/2)/(1+(aeb or 0))
end
function cb.bleedGain(heb,ieb,jeb,keb)
if(heb or 0)<=0 then
return 0
