db.INF_CAP=80
function db.evaluate(wub,xub)
local yub=db.run(wub,xub,{hpMul=1})
local zub={won=yub.won,wave=yub.wave,minutes=yub.t/60,aliveAt=yub.aliveAt,total=wub.total,at=os.time()}
if wub.infinite and db.unbound(wub.ld)then
zub.p=1
zub.margin=yub.won and string.format(ydd[2886],wub.total)or string.format(ydd[2887],yub.wave,yub.t/60)
elseif yub.won then
local Aub=db.run(wub,xub,{hpMul=1.3})
zub.p=Aub.won and 0.92 or 0.7
zub.margin=Aub.won and ydd[2888]or ydd[2889]
else
local Bub=db.run(wub,xub,{hpMul=0.75})
zub.p=Bub.won and 0.25 or 0.05
zub.margin=Bub.won and string.format(ydd[2890],yub.wave)or string.format(ydd[2891],yub.wave,wub.total)
if not Bub.won then
local Cub=db.run(wub,xub,{hpMul=0.25})
if not Cub.won then
zub.p,zub.hopeless=0.005,true
zub.margin=string.format(ydd[2892],yub.wave,wub.total)
end
end
end
return zub
end
db.STYLE_RUNS=20
function db.styleP(Dub,Eub)
local Fub=tonumber(Dub and Dub.p)or 0
if Fub<0.5 then
return Fub
end
Eub=Eub or((Dub.zone or Dub.style==ydd[2874])and ydd[2874]or ydd[2893])
local Gub,Hub=pcall(bb.hiveStyle,Eub)
if not(Gub and Hub)then
return Fub
end
local Iub=tonumber(Hub.predWin)or 0
local Jub=Q.clamp((tonumber(Hub.predWinWon)or 0)/math.max(1,Iub),0,1)
local Kub=Iub/(Iub+db.STYLE_RUNS)
return Fub*(1-Kub*(1-Jub))
end
function db.trust(Lub,Mub)
local Nub=Lub.cal or{}
if type(Nub.alive)~=ydd[1593]or Nub.teamSig~=db.sig((function()
local Oub={}
for Pub,Qub in ipairs(Mub)do
table.insert(Oub,Qub.u)
end
return Oub
end)())then
return nil
end
if Lub.key==ydd[1929]and not Nub.aliveLvl then
return nil
end
if Nub.aliveLvl and Lub.ld and Lub.ld.id and Nub.aliveLvl~=tostring(Lub.ld.id)..(ib.is(Lub.ld.id)and(ydd[2688]..tostring(Lub.ld.map))or ydd[520])then
return nil
end
local Rub=db.run(Lub,Mub,{hpMul=1})
local Sub,Tub,Uub=0,0,0
for Vub=3,math.min(Rub.wave,tonumber(Nub.lastWave)or 99)do
local Wub=tonumber(Nub.alive[tostring(Vub)])
local Xub=Rub.aliveAt[Vub]
if Wub and Xub and Wub>0 then
Sub=Sub+Wub
Tub=Tub+Xub
Uub=Uub+1
end
end
if Uub<2 or Tub<=0 then
return nil
end
local Yub=Sub/Tub
return{ratio=Yub,ok=Yub>=0.75 and Yub<=1.33,waves=Uub}
end
