if not _ub[dvb]and L.Units[dvb]and not R.isFarm(dvb)and R.rows(dvb)and not R.hidden(dvb)then
local evb,fvb=pcall(L.USC.calculate_level,dvb,tonumber(cvb.xp)or 0)
if evb and(tonumber(fvb)or 0)>=db.GROWN_LEVEL then
_ub[dvb]=true
avb=avb+1
end
end
end
return avb
end
function db.pool(gvb,hvb)
local ivb=L.session()
local jvb,kvb={},{}
local lvb=db.grownKinds()>=db.GROWN_MIN
for mvb,nvb in pairs(ivb.profile_data.collection.owned_units)do
local ovb=ivb.collection:get_unit_by_uuid(nvb.uuid)or nvb
local pvb,qvb=pcall(L.USC.calculate_level,ovb.unit_id,tonumber(ovb.xp)or 0)
local rvb=R.isFarm(ovb.unit_id)or not lvb or(pvb and(tonumber(qvb)or 0)>=db.GROWN_LEVEL)
if L.Units[ovb.unit_id]and R.rows(ovb.unit_id)and not R.hidden(ovb.unit_id)and rvb then
local svb=R.isFarm(ovb.unit_id)
local tvb,uvb=pcall(svb and function()
return R.farm(ovb,R.rows(ovb.unit_id).max)
end or R.score,ovb,gvb)
uvb=(tvb and uvb or 0)*(svb and 1 or R.skinMul(ovb,hvb and hvb.skinSet))
local vvb=svb and kvb or jvb
if not vvb[ovb.unit_id]or uvb>vvb[ovb.unit_id].sc then
vvb[ovb.unit_id]={u=ovb,sc=uvb}
end
end
end
local wvb,xvb={},{}
for yvb,zvb in pairs(jvb)do
table.insert(wvb,zvb)
end
for Avb,Bvb in pairs(kvb)do
table.insert(xvb,Bvb)
end
table.sort(wvb,function(Cvb,Dvb)
return Cvb.sc>Dvb.sc
end)
table.sort(xvb,function(Evb,Fvb)
return Evb.sc>Fvb.sc
end)
local Gvb={}
for Hvb=1,math.min(10,#wvb)do
table.insert(Gvb,wvb[Hvb].u)
end
local Ivb,Jvb={},{}
for Kvb=11,#wvb do
local Lvb=R.rows(wvb[Kvb].u.unit_id)
for Mvb=0,Lvb.max do
if Lvb[Mvb]and Lvb[Mvb].atk and R.attackInfo(Lvb[Mvb].atk,Lvb[Mvb].range).dot>0 then
table.insert(Mvb==0 and Ivb or Jvb,wvb[Kvb].u)
break
end
end
end
for Nvb=1,math.min(4,#Ivb)do
table.insert(Gvb,Ivb[Nvb])
end
for Ovb=1,math.min(2,#Jvb)do
table.insert(Gvb,Jvb[Ovb])
end
for Pvb=1,math.min(3,#xvb)do
table.insert(Gvb,xvb[Pvb].u)
end
local Qvb={}
for Rvb=11,#wvb do
local Svb=R.rows(wvb[Rvb].u.unit_id)[0]
local Tvb=Svb and Svb.atk and R.attackInfo(Svb.atk,Svb.range)
if Tvb and(Tvb.slowTime>0 or Tvb.stun>0)then
table.insert(Qvb,wvb[Rvb].u)
end
end
for Uvb=1,math.min(3,#Qvb)do
table.insert(Gvb,Qvb[Uvb])
end
for Vvb=11,#wvb do
local Wvb=wvb[Vvb].u.unit_id
if R.allyBuff(Wvb)or R.BLESS.by[Wvb]or R.GALE[Wvb]then
table.insert(Gvb,wvb[Vvb].u)
end
end
if hvb and((hvb.flyChance or 0)>0 or hvb.mapFly or(hvb.shield or 0)>0)then
local Xvb,Yvb={},{}
for Zvb=11,#wvb do
local _vb=wvb[Zvb].u
local awb=R.rows(_vb.unit_id)[0]
if R.airFrom(_vb.unit_id)==0 then
table.insert(Xvb,_vb)
end
local bwb,cwb=tonumber(awb and awb.cd)or 0,tonumber((L.Units[_vb.unit_id]or{}).cost)or 0
if bwb>0 and cwb>0 and R.range(_vb,0)>=15 then
local dwb=R.attackInfo(awb.atk,awb.range)
table.insert(Yvb,{u=_vb,v=dwb.n*dwb.hits/bwb/cwb*math.min(6,R.cap(_vb))})
end
end
table.sort(Yvb,function(ewb,fwb)
return ewb.v>fwb.v
end)
for gwb=1,math.min(4,#Xvb)do
table.insert(Gvb,Xvb[gwb])
end
for hwb=1,math.min(6,#Yvb)do
table.insert(Gvb,Yvb[hwb].u)
end
end
local iwb,jwb={},{}
for kwb,lwb in ipairs(Gvb)do
if not iwb[lwb]then
iwb[lwb]=true
table.insert(jwb,lwb)
end
end
jwb.rest={}
for mwb,nwb in ipairs(wvb)do
if not iwb[nwb.u]then
table.insert(jwb.rest,nwb.u)
end
end
return jwb
end
function db.objective(owb)
return(owb.won and 1000 or 0)+owb.wave*10-(owb.won and owb.t/60 or((owb.left or 1)*9-math.min(9,owb.t/60)))
end
db.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function db.cliff(pwb,qwb,rwb)
local swb
for twb,uwb in ipairs(db.LADDER)do
swb=db.run(pwb,qwb,{hpMul=uwb,layout=rwb})
if not swb.won then
return uwb,swb
end
end
return db.LADDER[#db.LADDER],swb
end
function db.exam(vwb,wwb)
local xwb,ywb,zwb=db.teamFrom(wwb,vwb.map),0,0
for Awb,Bwb in ipairs(db.LADDER)do
local Cwb,Dwb=0,0
for Ewb,Fwb in ipairs({0.92,1,1.08})do
local Gwb=db.run(vwb,xwb,{hpMul=Bwb*Fwb})
if Gwb.won then
Cwb=Cwb+1
end
Dwb=Dwb+Gwb.wave
end
ywb,zwb=ywb+Cwb,Dwb/3
task.wait()
if Cwb==0 then
break
end
end
return ywb,zwb
end
db.ZONE_CLOSE,db.ZONE_GAIN=1.3,20
function db.zoneKey(Hwb)
return tostring(Hwb.key)..ydd[1716]..tostring(Hwb.map)
end
function db.zoneChoice(Iwb,Jwb,Kwb,Lwb)
if M.killZone==false or Iwb.zone or(Iwb.infinite and db.unbound(Iwb.ld))then
return false
end
local Mwb=N.zoneRec[db.zoneKey(Iwb)]
local Nwb=Mwb and(Mwb.style==ydd[2874]or(Mwb.style==nil and Mwb.zone==true))
if Mwb and Mwb.won then
return Nwb==true,Nwb and ydd[2894]or nil
end
if Mwb and Nwb then
return false,ydd[2895]
end
local Owb=N.modes[Iwb.key]
local Pwb=Owb and tonumber(Owb.streak)or 0
if not Mwb and Owb and(tonumber(Owb.wins)or 0)>0 and Pwb==0 and Iwb.key~=ydd[1929]and Iwb.key~=ydd[1925]then
return false
end
local Qwb=Mwb~=nil or Pwb>0
local Rwb=Lwb and Kwb<=1 or(not Lwb and Kwb<=db.ZONE_CLOSE)
if not(Qwb or Rwb)then
return false
end
local Swb=table.clone(Iwb)
Swb.zone=true
local function Twb(Uwb)
local Vwb=0
for Wwb,Xwb in ipairs({0.92,1,1.08})do
Vwb=Vwb+db.objective(db.run(Uwb,Jwb,{hpMul=Kwb*Xwb}))
end
return Vwb/3
end
local Ywb=Twb(Swb)-Twb(Iwb)
if Qwb and Ywb> -db.ZONE_GAIN then
return true,ydd[2896],Ywb
end
