end
end
return bxb,cxb,dxb,exb
end
function db.bestTeam(mxb,nxb,oxb,pxb)
local qxb=Q.now()
pxb=pxb or 25
local rxb=table.clone(nxb)
local sxb,txb=db.cliff(mxb,db.teamFrom(rxb,mxb.map))
local function uxb(vxb)
local wxb=0
for xxb,yxb in ipairs(vxb)do
if R.isFarm(yxb.unit_id)then
wxb=wxb+1
end
end
return wxb
end
local zxb=uxb(oxb)>0
local function Axb(Bxb)
local Cxb=0
for Dxb,Exb in ipairs(Bxb)do
if not R.isFarm(Exb.unit_id)and not R.allyBuff(Exb.unit_id)then
Cxb=Cxb+R.cap(Exb)
end
end
return Cxb
end
local Fxb
while#rxb<6 do
local Gxb,Hxb
local Ixb=zxb and uxb(rxb)==0
for Jxb,Kxb in ipairs(oxb)do
local Lxb=false
for Mxb,Nxb in ipairs(rxb)do
if Nxb.unit_id==Kxb.unit_id then
Lxb=true
end
end
if not Lxb and(not Ixb or R.isFarm(Kxb.unit_id))then
local Oxb=table.clone(rxb)
table.insert(Oxb,Kxb)
local Pxb=db.run(mxb,db.teamFrom(Oxb,mxb.map),{hpMul=sxb})
local Qxb=db.objective(Pxb)
if not Hxb or Qxb>Hxb then
Gxb,Hxb,Fxb=Kxb,Qxb,Pxb
end
end
end
if not Gxb then
break
end
table.insert(rxb,Gxb)
end
if zxb and uxb(rxb)==0 then
local Rxb,Sxb
for Txb=1,#rxb do
for Uxb,Vxb in ipairs(oxb)do
if R.isFarm(Vxb.unit_id)then
local Wxb=table.clone(rxb)
Wxb[Txb]=Vxb
local Xxb=db.run(mxb,db.teamFrom(Wxb,mxb.map),{hpMul=sxb})
local Yxb=db.objective(Xxb)
if not Sxb or Yxb>Sxb then
Rxb,Sxb,Fxb=Wxb,Yxb,Xxb
end
end
end
end
if Rxb then
rxb=Rxb
end
end
local function Zxb(_xb,ayb)
local byb=db.teamFrom(_xb,mxb.map)
return(db.objective(ayb)+db.objective(db.run(mxb,byb,{hpMul=sxb*0.92}))+db.objective(db.run(mxb,byb,{hpMul=sxb*1.08})))/3
end
local cyb,dyb=Fxb or txb,Zxb(rxb,Fxb or txb)
if type(oxb.rest)==ydd[1593]and#oxb.rest>0 then
local eyb,fyb
for gyb,hyb in ipairs(rxb)do
if not R.isFarm(hyb.unit_id)and not R.allyBuff(hyb.unit_id)then
local iyb,jyb=pcall(R.score,hyb,mxb.mod)
jyb=(iyb and jyb or 0)*R.skinMul(hyb,mxb.skinSet)
if not fyb or jyb<fyb then
eyb,fyb=gyb,jyb
end
end
end
if eyb then
local kyb,lyb={},Q.now()
for myb,nyb in ipairs(oxb.rest)do
if Q.now()-lyb>5 then
break
end
local oyb=false
for pyb,qyb in ipairs(rxb)do
if qyb.unit_id==nyb.unit_id then
oyb=true
end
end
if not oyb then
local ryb=table.clone(rxb)
ryb[eyb]=nyb
table.insert(kyb,{u=nyb,o=db.objective(db.run(mxb,db.teamFrom(ryb,mxb.map),{hpMul=sxb}))})
end
end
table.sort(kyb,function(syb,tyb)
return syb.o>tyb.o
end)
oxb=table.clone(oxb)
for uyb=1,math.min(4,#kyb)do
table.insert(oxb,1,kyb[uyb].u)
end
qxb=qxb+(Q.now()-lyb)
end
end
for vyb=1,2 do
local wyb=false
for xyb=1,#rxb do
for yyb,zyb in ipairs(oxb)do
if Q.now()-qxb>pxb then
return rxb,cyb,sxb,txb
end
local Ayb=false
for Byb,Cyb in ipairs(rxb)do
if Cyb.unit_id==zyb.unit_id then
Ayb=true
end
end
if not Ayb then
local Dyb=table.clone(rxb)
Dyb[xyb]=zyb
if(not zxb or uxb(Dyb)>0)and Axb(Dyb)>=math.min(8,Axb(rxb))then
local Eyb=db.run(mxb,db.teamFrom(Dyb,mxb.map),{hpMul=sxb})
local Fyb=db.objective(Eyb)
if Fyb>dyb+1 then
Fyb=Zxb(Dyb,Eyb)
if Fyb>dyb+1 then
rxb,dyb,cyb,wyb=Dyb,Fyb,Eyb,true
end
end
end
end
end
end
if not wyb then
break
end
end
return rxb,cyb,sxb,txb
end
function db.evolutions()
local Gyb=L.session()
