if Pyb and Pyb.evolve and Pyb.evolve.evolve_unit and not Pyb.evolve.hide_from_ui and not Iyb[Oyb.unit_id]and L.Units[Pyb.evolve.evolve_unit]then
Iyb[Oyb.unit_id]=true
