if Yyb.unit_id==Vyb.unit_id and(not Vyb.shiny or Yyb.shiny)then
Wyb=Wyb+1
end
end
if Wyb<(Vyb.amount or 1)then
table.insert(Ryb,string.format(ydd[2211],R.name(Vyb.unit_id),Wyb,Vyb.amount))
end
end
local Zyb=eb.killsShort(Gyb.collection:get_unit_by_uuid(Oyb.uuid)or Oyb,Qyb)
if Zyb then
table.insert(Ryb,string.format(ydd[2500],Zyb.what,Q.fmt(Zyb.have),Q.fmt(Zyb.need)))
end
if#Ryb<=1 then
local _yb=Gyb.collection:get_unit_by_uuid(Oyb.uuid)or Oyb
table.insert(Hyb,{u=_yb,from=Oyb.unit_id,to=Pyb.evolve.evolve_unit,missing=Ryb,evolved={unit_id=Pyb.evolve.evolve_unit,uuid=ydd[2202]..tostring(_yb.uuid),xp=_yb.xp,traits=_yb.traits,trait_stats=_yb.trait_stats,further_modifiers=_yb.further_modifiers}})
end
end
end
end
return Hyb
end
function db.levelFor(azb)
