end
function W.blockedSpot(XOb)
local YOb=W.spotKey(XOb)
if W.refused[YOb]then
return true
end
local ZOb=N.blocked[W.mapKey()]
return ZOb and(tonumber(ZOb[YOb])or 0)>=2
end
function W.valid(_Ob,aPb)
local bPb=L.PC.raycast(_Ob+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not bPb then
return nil
end
if not L.PC.is_valid_raycast_hit(bPb.Instance,aPb)then
return nil
end
local cPb=bPb.Position
if W.blockedSpot(cPb)then
return nil
end
local dPb=(tonumber(aPb.override_hitbox_radius)or 1.5)+0.25
W.probe.Size=Vector3 .new(dPb*2,2.5,dPb*2)
W.probe.CFrame=CFrame.new(cPb+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(W.probe,W.overlap)>0 then
return nil
end
for ePb,fPb in ipairs(W.mine or{})do
local gPb=fPb:FindFirstChild(ydd[3212])
local hPb=gPb and gPb.Position or fPb:GetPivot().Position
local iPb=gPb and math.max(gPb.Size.X,gPb.Size.Z)/2 or 1.5
if(Q.flat(cPb)-Q.flat(hPb)).Magnitude<dPb+iPb then
return nil
end
end
return cPb
end
function W.buildCandidates()
W.cands={}
local jPb={}
for kPb=1,#W.samples,3 do
local lPb=W.samples[kPb]
local mPb=W.samples[math.min(#W.samples,kPb+1)]
local nPb=Q.flat(mPb.pos-lPb.pos)
if nPb.Magnitude<0.01 then
nPb=Vector3 .new(1,0,0)
end
nPb=nPb.Unit
local oPb=Vector3 .new(-nPb.Z,0,nPb.X)
for pPb,qPb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for rPb,sPb in ipairs({1,-1})do
local tPb=lPb.pos+oPb*qPb*sPb
local uPb=string.format(ydd[3211],math.floor(tPb.X/1.5),math.floor(tPb.Z/1.5))
if not jPb[uPb]then
jPb[uPb]=true
table.insert(W.cands,tPb)
end
end
end
end
end
function W.coverage(vPb,wPb)
local xPb={}
for yPb,zPb in ipairs(vPb)do
local APb=zPb._stats
if not R.isFarm(APb.id.Value)and APb:FindFirstChild(ydd[1751])then
table.insert(xPb,{p=Q.flat(zPb:GetPivot().Position),r=APb.range.Value*(R.SUMMONER[APb.id.Value]and R.SUMMONER[APb.id.Value].reach or 1),air=W.canAir(zPb)})
end
end
local BPb,CPb=0,0
if#xPb>0 then
for DPb,EPb in ipairs(W.samples)do
if EPb.prog>CPb then
local FPb=Q.flat(EPb.pos)
for GPb,HPb in ipairs(xPb)do
if(FPb-HPb.p).Magnitude<=HPb.r then
if EPb.prog>BPb then
BPb=EPb.prog
end
if HPb.air then
CPb=EPb.prog
break
end
end
end
end
end
end
local IPb,JPb={},W.laneCount
if JPb and JPb.n>=2 and#xPb>0 then
local KPb={}
for LPb,MPb in ipairs(W.samples)do
local NPb=Q.flat(MPb.pos)
for OPb,PPb in ipairs(xPb)do
if(NPb-PPb.p).Magnitude<=PPb.r then
local QPb=tostring(MPb.lane)
KPb[QPb]=(KPb[QPb]or 0)+1
if MPb.prog>(IPb[QPb]or 0)then
IPb[QPb]=MPb.prog
end
break
end
end
end
local RPb,SPb={},0
for TPb,UPb in pairs(JPb.by)do
RPb[TPb]=(KPb[TPb]or 0)/math.max(1,UPb)
SPb=math.max(SPb,RPb[TPb])
end
W.laneW={}
for VPb,WPb in pairs(JPb.by)do
W.laneW[VPb]=(JPb.avg/math.max(1,WPb))*(1+1.5*(SPb>0 and(1-RPb[VPb]/SPb)or 0))
end
W.laneFrac=RPb
else
W.laneW,W.laneFrac=nil,nil
end
local XPb,YPb,ZPb
if#xPb>0 then
for _Pb,aQb in ipairs(wPb)do
local bQb=(W.laneW and aQb.lane)and(IPb[tostring(aQb.lane)]or 0)or BPb
if aQb.hp>0 and aQb.prog>bQb+0.02 and aQb.prog>(XPb or 0)then
XPb,ZPb=aQb.prog,W.laneW and aQb.lane or nil
end
if aQb.hp>0 and aQb.fly and aQb.prog>CPb+0.02 then
YPb=true
end
end
end
local cQb= #xPb>0 and(W.pressure or 0)>=BPb-0.08
return{covEnd=BPb,airEnd=CPb,leak=XPb,leakLane=ZPb,covL=IPb,airLeak=YPb,push=cQb,units= #xPb}
end
function W.needLastLine(dQb)
if R.isFarm(dQb.id)or R.allyBuff(dQb.id)or W.fieldCount()<5 then
return false
end
local eQb,fQb=0,0
for gQb,hQb in ipairs(W.mine or{})do
local iQb=hQb._stats
if not R.isFarm(iQb.id.Value)and iQb:FindFirstChild(ydd[1751])then
local jQb,kQb=Q.flat(hQb:GetPivot().Position),iQb.range.Value
for lQb,mQb in ipairs(W.samples)do
if mQb.prog>=0.85 and(Q.flat(mQb.pos)-jQb).Magnitude<=kQb then
eQb=eQb+1
if W.canAir(hQb)then
fQb=fQb+1
end
break
end
end
end
end
return eQb<2 or(fQb<1 and W.flyMode()and W.cardAir(dQb.id))
end
W.airCache=setmetatable({},{__mode=ydd[1796]})
function W.canAir(nQb)
local oQb=nQb._stats:FindFirstChild(ydd[1680])and nQb._stats.upgrade.Value or 0
local pQb=W.airCache[nQb]
if not pQb or pQb.lvl~=oQb then
local qQb=nQb:GetAttribute(ydd[3213])==true or nQb:GetAttribute(ydd[3214])==true
pQb={lvl=oQb,v=qQb}
W.airCache[nQb]=pQb
