return pQb.v
end
R._airFrom={}
function R.airFrom(rQb)
local sQb=R._airFrom[rQb]
if sQb~=nil then
return sQb or nil
end
local tQb=L.Units[rQb]
if tQb and(tQb.hill_unit or tQb.hybrid_placement or R.SUMMONER[rQb])then
R._airFrom[rQb]=0
return 0
end
local uQb=R.rows(rQb)
if not(uQb and uQb.max)then
return W.cardAir(rQb)and 0 or nil
end
local vQb=false
for wQb=0,uQb.max do
local xQb=uQb[wQb]and uQb[wQb].atk
if xQb and L.Attacks[xQb]and L.Attacks[xQb].targets_flying then
vQb=wQb
break
end
end
if vQb==false and W.cardAir(rQb)then
vQb=0
end
R._airFrom[rQb]=vQb
return vQb or nil
end
function W.cardAir(yQb)
local zQb=L.Units[yQb]
if not zQb then
return false
end
if zQb.hill_unit or zQb.hybrid_placement then
return true
end
local AQb=R.field(yQb,ydd[1694])or R.field(yQb,ydd[1693])
return AQb and L.Attacks[AQb]and L.Attacks[AQb].targets_flying and true or false
end
function W.airShare()
local BQb,CQb=0,0
for DQb,EQb in ipairs(W.mine or{})do
local FQb=EQb._stats.id.Value
if not R.isFarm(FQb)then
local GQb,HQb=pcall(W.liveDps,EQb,FQb)
HQb=GQb and HQb or 0
BQb=BQb+HQb
if W.canAir(EQb)then
CQb=CQb+HQb
end
end
end
return BQb>0 and CQb/BQb or 0
end
function W.cover(IQb,JQb,KQb,LQb)
local MQb=0
local NQb=Q.flat(IQb)
local OQb=KQb and N.maps[W.mapKey()]and N.maps[W.mapKey()].dens
local PQb=W.laneW
for QQb,RQb in ipairs(W.samples)do
if(Q.flat(RQb.pos)-NQb).Magnitude<=JQb then
local SQb=1
if OQb then
SQb=0.15+0.85*(tonumber(OQb[math.min(db.BINS,math.floor(RQb.prog*db.BINS)+1)])or 0)
end
if PQb then
SQb=SQb*(PQb[tostring(RQb.lane)]or 1)
end
if LQb then
if LQb.leak and RQb.prog>=LQb.leak-0.01 and(not LQb.leakLane or tostring(RQb.lane)==LQb.leakLane)then
SQb=SQb+3
elseif LQb.push and RQb.prog>LQb.covEnd then
SQb=SQb+0.6
end
end
MQb=MQb+SQb
end
end
return MQb
end
