function W.learn()
local lfc=W.calRun and W.calRun.potBy
if type(lfc)~=ydd[1593]then
return
end
pcall(W.sampleHelpers,true)
local mfc={}
for nfc,ofc in pairs(W.ownDealt or{})do
if not R.isFarm(ofc.id)then
mfc[ofc.id]=(mfc[ofc.id]or 0)+(tonumber(ofc.v)or 0)
end
end
for pfc,qfc in pairs(W.helperDealt or{})do
if qfc.owner and R.SUMMONER[qfc.owner]then
mfc[qfc.owner]=(mfc[qfc.owner]or 0)+(tonumber(qfc.v)or 0)
end
end
local rfc,sfc=0,0
for tfc,ufc in pairs(lfc)do
if ufc>0 then
rfc=rfc+(mfc[tfc]or 0)
sfc=sfc+ufc
end
end
if rfc<=0 or sfc<=0 then
return
end
local vfc=rfc/sfc
W.lastEff={}
for wfc,xfc in pairs(lfc)do
if xfc>0 and xfc/sfc>0.02 then
local yfc=N.learn[wfc]or{eff=1,n=0}
local zfc=math.max(0.02,0.25*math.sqrt(30/(30+yfc.n)))
local Afc=Q.clamp(((mfc[wfc]or 0)/xfc)/vfc,0.3,3)
W.lastEff[wfc]=math.floor(Afc*1000+0.5)/1000
yfc.eff=yfc.eff+(Afc-yfc.eff)*zfc
yfc.n=yfc.n+1
N.learn[wfc]=yfc
end
end
local Bfc=R.mapKey((W.info and W.info.map)or(W.ld and W.ld.map))
if Bfc and next(W.lastEff)then
N.mapLearn=type(N.mapLearn)==ydd[1593]and N.mapLearn or{}
local Cfc=type(N.mapLearn[Bfc])==ydd[1593]and N.mapLearn[Bfc]or{}
for Dfc,Efc in pairs(W.lastEff)do
local Ffc=type(Cfc[Dfc])==ydd[1593]and Cfc[Dfc]or{eff=Efc,n=0}
local Gfc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Ffc.n)or 0))))
Ffc.eff=(tonumber(Ffc.n)or 0)==0 and Efc or((tonumber(Ffc.eff)or Efc)+(Efc-(tonumber(Ffc.eff)or Efc))*Gfc)
Ffc.n=(tonumber(Ffc.n)or 0)+1
Cfc[Dfc]=Ffc
end
Cfc._at=os.time()
N.mapLearn[Bfc]=Cfc
if Q.count(N.mapLearn)>80 then
local Hfc,Ifc
for Jfc,Kfc in pairs(N.mapLearn)do
if not Ifc or(tonumber(Kfc._at)or 0)<Ifc then
Hfc,Ifc=Jfc,tonumber(Kfc._at)or 0
end
end
N.mapLearn[Hfc]=nil
end
end
end
