W.BASE_WIN,W.BASE_MARGIN,W.BASE_SOON,W.BASE_END=10,1.3,45,0.97
function W.baseVerdict(plc,qlc)
local rlc=(qlc.t or 0)-(plc.t or 0)
if rlc<W.BASE_WIN-1 then
return false
end
local slc=((tonumber(plc.base)or 0)-(tonumber(qlc.base)or 0))/rlc
if slc<=0 or(tonumber(qlc.base)or 0)<=0 then
return false
end
local tlc=qlc.base/slc
local ulc,vlc=0,0
local wlc,xlc=plc.foes or{},qlc.foes or{}
for ylc,zlc in pairs(xlc)do
if zlc.prog>=W.BASE_END then
ulc=ulc+zlc.hp
local Alc=wlc[ylc]
if Alc then
vlc=vlc+math.max(0,Alc.hp-zlc.hp)
end
end
end
for Blc,Clc in pairs(wlc)do
if Clc.prog>=W.BASE_END and not xlc[Blc]then
vlc=vlc+Clc.hp
end
end
if ulc<=0 then
return false
end
local Dlc=vlc/rlc
local Elc=Dlc>0 and ulc/Dlc or math.huge
local Flc={baseTime=tlc,loss=slc,atEnd=ulc,rate=Dlc,killTime=Elc}
return tlc<W.BASE_SOON and Elc>tlc*W.BASE_MARGIN,Flc
end
