N.dg.bail={sig=U.teamSig(),at=os.time()}
pcall(W.styleRecord,false)
pcall(gb.roomLearn,false)
E.log(1,ydd[2680],string.format(ydd[3552],math.floor(100*Llc.base/math.max(1,Llc.baseMax)+0.5),Q.fmt(Qlc.loss),math.floor(Qlc.baseTime),Q.fmt(Qlc.atEnd),Q.fmt(Qlc.rate),Qlc.killTime==math.huge and ydd[3553]or(math.floor(Qlc.killTime)..ydd[1441])))
