elseif KRc.copies then
GRc[KRc.copies]=true
table.insert(DRc,{ydd[4244]..R.name(KRc.copies),string.format(ydd[4245],LRc,MRc),p=KRc})
elseif KRc.item then
FRc[KRc.item]=true
local NRc=(L.Items[KRc.item]or{}).name or tostring(KRc.item)
local ORc
if KRc.unknown then
ORc=ydd[4246]
elseif KRc.portal then
local PRc=U.PORTALS[KRc.portal]
ORc=string.format(ydd[4247],(L.Items[KRc.portal]or{}).name or tostring(KRc.portal),#U.portalsHeld(KRc.portal),PRc and(ydd[4248]..U.levelName(PRc.from)..ydd[4249])or ydd[520])
elseif KRc.eventShop then
ORc=string.format(ydd[4250],CRc.comma(L.cur(KRc.currency)),CRc.comma(KRc.cost),tostring(KRc.currency))
elseif KRc.shopKey then
ORc=string.format(ydd[4251],CRc.comma(eb.have(KRc.costItem)),CRc.comma((tonumber(KRc.cost)or 0)*(MRc-LRc)),(L.Items[KRc.costItem]or{}).name or tostring(KRc.costItem))
else
local QRc=KRc.best or(KRc.levels and KRc.levels[1])
local RRc=QRc and(tonumber(QRc.per)or 0)>0 and math.ceil((MRc-LRc)/QRc.per)or nil
ORc=QRc and string.format(ydd[4252],U.levelName(QRc.level),HRc(QRc.per),RRc and string.format(ydd[4253],RRc)or ydd[520])or ydd[4246]
end
table.insert(DRc,{NRc,string.format(ydd[4254],CRc.comma(LRc),CRc.comma(MRc),ORc),p=KRc})
end
end
for SRc,TRc in ipairs(BRc.items or{})do
if not FRc[TRc.id]then
table.insert(ERc,string.format(ydd[4255],(L.Items[TRc.id]or{}).name or tostring(TRc.id),CRc.comma(eb.have(TRc.id)),CRc.comma(TRc.amount)))
end
