end
end
local WRc=DRc[1]
return DRc,ERc,WRc and(WRc[1]..ydd[1924]..(WRc[2]:match(ydd[4257])or WRc[2]))or ydd[4258]
end
function jb.evoProgress(XRc)
if XRc.ready then
return 1
end
local YRc,ZRc,_Rc=0,0,{}
for aSc,bSc in ipairs(XRc.plans or{})do
local cSc=tonumber(bSc.need)or 0
if bSc.item then
_Rc[bSc.item]=true
end
if cSc>0 then
YRc=YRc+math.min(1,(tonumber(bSc.have)or 0)/cSc)
ZRc=ZRc+1
end
end
for dSc,eSc in ipairs(XRc.items or{})do
if not _Rc[eSc.id]then
YRc=YRc+1
ZRc=ZRc+1
end
end
return ZRc>0 and YRc/ZRc or 0
end
